2: /*-------------------------------------------------------------------------*/
3: /**
4:    @file    iniparser.c
5:    @author  N. Devillard
6:    @brief   Parser for ini files.
7: */
8: /*--------------------------------------------------------------------------*/
9: /*---------------------------- Includes ------------------------------------*/
10: #include <ctype.h>
11: #include <stdarg.h>
12: #include <stdlib.h>
13: #include <string.h>
14: #include <inttypes.h>
15: #include "iniparser.h"
16: 
17: /*---------------------------- Defines -------------------------------------*/
18: #define ASCIILINESZ         (1024)
19: #define INI_INVALID_KEY     ((char*)-1)
20: 
21: /*---------------------------------------------------------------------------
22:                         Private to this module
23:  ---------------------------------------------------------------------------*/
24: /**
25:  * This enum stores the status for each parsed line (internal use only).
26:  */
27: typedef enum _line_status_ {
28:     LINE_UNPROCESSED,
29:     LINE_ERROR,
30:     LINE_EMPTY,
31:     LINE_COMMENT,
32:     LINE_SECTION,
33:     LINE_VALUE
34: } line_status ;
35: 
36: /*-------------------------------------------------------------------------*/
37: /**
38:   @brief    Convert a string to lowercase.
39:   @param    in   String to convert.
40:   @param    out Output buffer.
41:   @param    len Size of the out buffer.
42:   @return   ptr to the out buffer or NULL if an error occured.
43: 
44:   This function convert a string into lowercase.
45:   At most len - 1 elements of the input string will be converted.
46:  */
47: /*--------------------------------------------------------------------------*/
48: static const char * strlwc(const char * in, char *out, unsigned len)
49: {
50:     unsigned i ;
51: 
52:     if (in==NULL || out == NULL || len==0) return NULL ;
53:     i=0 ;
54:     while (in[i] != '\0' && i < len-1) {
55:         out[i] = (char)tolower((int)in[i]);
56:         i++ ;
57:     }
58:     out[i] = '\0';
59:     return out ;
60: }
61: 
62: /*-------------------------------------------------------------------------*/
63: /**
64:   @brief    Duplicate a string
65:   @param    s String to duplicate
66:   @return   Pointer to a newly allocated string, to be freed with free()
67: 
68:   This is a replacement for strdup(). This implementation is provided
69:   for systems that do not have it.
70:  */
71: /*--------------------------------------------------------------------------*/
72: static char * xstrdup(const char * s)
73: {
74:     char * t ;
75:     size_t len ;
76:     if (!s)
77:         return NULL ;
78: 
79:     len = strlen(s) + 1 ;
80:     t = (char*) malloc(len) ;
81:     if (t) {
82:         memcpy(t, s, len) ;
83:     }
84:     return t ;
85: }
86: 
87: /*-------------------------------------------------------------------------*/
88: /**
89:   @brief    Remove blanks at the beginning and the end of a string.
90:   @param    str  String to parse and alter.
91:   @return   unsigned New size of the string.
92:  */
93: /*--------------------------------------------------------------------------*/
94: static unsigned strstrip(char * s)
95: {
96:     char *last = NULL ;
97:     char *dest = s;
98: 
99:     if (s==NULL) return 0;
100: 
101:     last = s + strlen(s);
102:     while (isspace((unsigned char)*s) && *s) s++;
103:     while (last > s) {
104:         if (!isspace((unsigned char)*(last-1)))
105:             break ;
106:         last -- ;
107:     }
108:     *last = (char)0;
109: 
110:     memmove(dest,s,last - s + 1);
111:     return last - s;
112: }
113: 
114: /*-------------------------------------------------------------------------*/
115: /**
116:   @brief    Default error callback for iniparser: wraps `fprintf(stderr, ...)`.
117:  */
118: /*--------------------------------------------------------------------------*/
119: static int default_error_callback(const char *format, ...)
120: {
121:   int ret;
122:   va_list argptr;
123:   va_start(argptr, format);
124:   ret = vfprintf(stderr, format, argptr);
125:   va_end(argptr);
126:   return ret;
127: }
128: 
129: static int (*iniparser_error_callback)(const char*, ...) = default_error_callback;
130: 
131: /*-------------------------------------------------------------------------*/
132: /**
133:   @brief    Configure a function to receive the error messages.
134:   @param    errback  Function to call.
135: 
136:   By default, the error will be printed on stderr. If a null pointer is passed
137:   as errback the error callback will be switched back to default.
138:  */
139: /*--------------------------------------------------------------------------*/
140: void iniparser_set_error_callback(int (*errback)(const char *, ...))
141: {
142:   if (errback) {
143:     iniparser_error_callback = errback;
144:   } else {
145:     iniparser_error_callback = default_error_callback;
146:   }
147: }
148: 
149: /*-------------------------------------------------------------------------*/
150: /**
151:   @brief    Get number of sections in a dictionary
152:   @param    d   Dictionary to examine
153:   @return   int Number of sections found in dictionary
154: 
155:   This function returns the number of sections found in a dictionary.
156:   The test to recognize sections is done on the string stored in the
157:   dictionary: a section name is given as "section" whereas a key is
158:   stored as "section:key", thus the test looks for entries that do not
159:   contain a colon.
160: 
161:   This clearly fails in the case a section name contains a colon, but
162:   this should simply be avoided.
163: 
164:   This function returns -1 in case of error.
165:  */
166: /*--------------------------------------------------------------------------*/
167: int iniparser_getnsec(const dictionary * d)
168: {
169:     size_t i ;
170:     int nsec ;
171: 
172:     if (d==NULL) return -1 ;
173:     nsec=0 ;
174:     for (i=0 ; i<d->size ; i++) {
175:         if (d->key[i]==NULL)
176:             continue ;
177:         if (strchr(d->key[i], ':')==NULL) {
178:             nsec ++ ;
179:         }
180:     }
181:     return nsec ;
182: }
183: 
184: /*-------------------------------------------------------------------------*/
185: /**
186:   @brief    Get name for section n in a dictionary.
187:   @param    d   Dictionary to examine
188:   @param    n   Section number (from 0 to nsec-1).
189:   @return   Pointer to char string
190: 
191:   This function locates the n-th section in a dictionary and returns
192:   its name as a pointer to a string statically allocated inside the
193:   dictionary. Do not free or modify the returned string!
194: 
195:   This function returns NULL in case of error.
196:  */
197: /*--------------------------------------------------------------------------*/
198: const char * iniparser_getsecname(const dictionary * d, int n)
199: {
200:     size_t i ;
201:     int foundsec ;
202: 
203:     if (d==NULL || n<0) return NULL ;
204:     foundsec=0 ;
205:     for (i=0 ; i<d->size ; i++) {
206:         if (d->key[i]==NULL)
207:             continue ;
208:         if (strchr(d->key[i], ':')==NULL) {
209:             foundsec++ ;
210:             if (foundsec>n)
211:                 break ;
212:         }
213:     }
214:     if (foundsec<=n) {
215:         return NULL ;
216:     }
217:     return d->key[i] ;
218: }
