220: /*-------------------------------------------------------------------------*/
221: /**
222:   @brief    Dump a dictionary to an opened file pointer.
223:   @param    d   Dictionary to dump.
224:   @param    f   Opened file pointer to dump to.
225:   @return   void
226: 
227:   This function prints out the contents of a dictionary, one element by
228:   line, onto the provided file pointer. It is OK to specify @c stderr
229:   or @c stdout as output files. This function is meant for debugging
230:   purposes mostly.
231:  */
232: /*--------------------------------------------------------------------------*/
233: void iniparser_dump(const dictionary * d, FILE * f)
234: {
235:     size_t i ;
236: 
237:     if (d==NULL || f==NULL) return ;
238:     for (i=0 ; i<d->size ; i++) {
239:         if (d->key[i]==NULL)
240:             continue ;
241:         if (d->val[i]!=NULL) {
242:             fprintf(f, "[%s]=[%s]\n", d->key[i], d->val[i]);
243:         } else {
244:             fprintf(f, "[%s]=UNDEF\n", d->key[i]);
245:         }
246:     }
247:     return ;
248: }
249: 
250: static void escape_value(char *escaped, char *value) {
251:     char c;
252:     int v = 0;
253:     int e = 0;
254: 
255:     if(!escaped || !value)
256:         return;
257: 
258:     while((c = value[v]) != '\0') {
259:         if(c == '\\' || c == '"') {
260:             escaped[e] = '\\';
261:             e++;
262:         }
263:         escaped[e] = c;
264:         v++;
265:         e++;
266:     }
267:     escaped[e] = '\0';
268: }
