270: /*-------------------------------------------------------------------------*/
271: /**
272:   @brief    Save a dictionary to a loadable ini file
273:   @param    d   Dictionary to dump
274:   @param    f   Opened file pointer to dump to
275:   @return   void
276: 
277:   This function dumps a given dictionary into a loadable ini file.
278:   It is Ok to specify @c stderr or @c stdout as output files.
279:  */
280: /*--------------------------------------------------------------------------*/
281: void iniparser_dump_ini(const dictionary * d, FILE * f)
282: {
283:     size_t       i ;
284:     size_t       nsec ;
285:     const char * secname ;
286:     char escaped[(ASCIILINESZ * 2) + 2] = "";
287: 
288:     if (d==NULL || f==NULL) return ;
289: 
290:     nsec = iniparser_getnsec(d);
291:     if (nsec<1) {
292:         /* No section in file: dump all keys as they are */
293:         for (i=0 ; i<d->size ; i++) {
294:             if (d->key[i]==NULL)
295:                 continue ;
296:             escape_value(escaped, d->val[i]);
297:             fprintf(f, "%s = \"%s\"\n", d->key[i], escaped);
298:         }
299:         return ;
300:     }
301:     for (i=0 ; i<nsec ; i++) {
302:         secname = iniparser_getsecname(d, i) ;
303:         iniparser_dumpsection_ini(d, secname, f);
304:     }
305:     fprintf(f, "\n");
306:     return ;
307: }
