309: /*-------------------------------------------------------------------------*/
310: /**
311:   @brief    Save a dictionary section to a loadable ini file
312:   @param    d   Dictionary to dump
313:   @param    s   Section name of dictionary to dump
314:   @param    f   Opened file pointer to dump to
315:   @return   void
316: 
317:   This function dumps a given section of a given dictionary into a loadable ini
318:   file.  It is Ok to specify @c stderr or @c stdout as output files.
319:  */
320: /*--------------------------------------------------------------------------*/
321: void iniparser_dumpsection_ini(const dictionary * d, const char * s, FILE * f)
322: {
323:     size_t  j ;
324:     char    keym[ASCIILINESZ+1];
325:     int     seclen ;
326:     char escaped[(ASCIILINESZ * 2) + 2] = "";
327: 
328:     if (d==NULL || f==NULL) return;
329:     if (! iniparser_find_entry(d, s)) return;
330:     if (strlen(s) > sizeof(keym)) return;
331: 
332:     seclen  = (int)strlen(s);
333:     fprintf(f, "\n[%s]\n", s);
334:     sprintf(keym, "%s:", s);
335:     for (j=0 ; j<d->size ; j++) {
336:         if (d->key[j]==NULL)
337:             continue ;
338:         if (!strncmp(d->key[j], keym, seclen+1)) {
339:             escape_value(escaped, d->val[j]);
340:             fprintf(f, "%-30s = \"%s\"\n", d->key[j]+seclen+1, escaped);
341:         }
342:     }
343:     fprintf(f, "\n");
344:     return ;
345: }
