381: /*-------------------------------------------------------------------------*/
382: /**
383:   @brief    Get the number of keys in a section of a dictionary.
384:   @param    d    Dictionary to examine
385:   @param    s    Section name of dictionary to examine
386:   @param    keys Already allocated array to store the keys in
387:   @return   The pointer passed as `keys` argument or NULL in case of error
388: 
389:   This function queries a dictionary and finds all keys in a given section.
390:   The keys argument should be an array of pointers which size has been
391:   determined by calling `iniparser_getsecnkeys` function prior to this one.
392: 
393:   Each pointer in the returned char pointer-to-pointer is pointing to
394:   a string allocated in the dictionary; do not free or modify them.
395:  */
396: /*--------------------------------------------------------------------------*/
397: const char ** iniparser_getseckeys(const dictionary * d, const char * s, const char ** keys)
398: {
399:     size_t i, j, seclen ;
400:     char keym[ASCIILINESZ+1];
401: 
402:     if (d==NULL || keys==NULL) return NULL;
403:     if (! iniparser_find_entry(d, s)) return NULL;
404: 
405:     seclen  = strlen(s);
406:     strlwc(s, keym, sizeof(keym));
407:     keym[seclen] = ':';
408: 
409:     i = 0;
410: 
411:     for (j=0 ; j<d->size ; j++) {
412:         if (d->key[j]==NULL)
413:             continue ;
414:         if (!strncmp(d->key[j], keym, seclen+1)) {
415:             keys[i] = d->key[j];
416:             i++;
417:         }
418:     }
419: 
420:     return keys;
421: }
