562: /*-------------------------------------------------------------------------*/
563: /**
564:   @brief    Get the string associated to a key, convert to a boolean
565:   @param    d Dictionary to search
566:   @param    key Key string to look for
567:   @param    notfound Value to return in case of error
568:   @return   integer
569: 
570:   This function queries a dictionary for a key. A key as read from an
571:   ini file is given as "section:key". If the key cannot be found,
572:   the notfound value is returned.
573: 
574:   A true boolean is found if one of the following is matched:
575: 
576:   - A string starting with 'y'
577:   - A string starting with 'Y'
578:   - A string starting with 't'
579:   - A string starting with 'T'
580:   - A string starting with '1'
581: 
582:   A false boolean is found if one of the following is matched:
583: 
584:   - A string starting with 'n'
585:   - A string starting with 'N'
586:   - A string starting with 'f'
587:   - A string starting with 'F'
588:   - A string starting with '0'
589: 
590:   The notfound value returned if no boolean is identified, does not
591:   necessarily have to be 0 or 1.
592:  */
593: /*--------------------------------------------------------------------------*/
594: int iniparser_getboolean(const dictionary * d, const char * key, int notfound)
595: {
596:     int          ret ;
597:     const char * c ;
598: 
599:     c = iniparser_getstring(d, key, INI_INVALID_KEY);
600:     if (c==NULL || c==INI_INVALID_KEY) return notfound ;
601:     if (c[0]=='y' || c[0]=='Y' || c[0]=='1' || c[0]=='t' || c[0]=='T') {
602:         ret = 1 ;
603:     } else if (c[0]=='n' || c[0]=='N' || c[0]=='0' || c[0]=='f' || c[0]=='F') {
604:         ret = 0 ;
605:     } else {
606:         ret = notfound ;
607:     }
608:     return ret;
609: }
