54: /*-------------------------------------------------------------------------*/
55: /**
56:   @brief    Double the size of the dictionary
57:   @param    d Dictionary to grow
58:   @return   This function returns non-zero in case of failure
59:  */
60: /*--------------------------------------------------------------------------*/
61: static int dictionary_grow(dictionary * d)
62: {
63:     char        ** new_val ;
64:     char        ** new_key ;
65:     unsigned     * new_hash ;
66: 
67:     new_val  = (char**) calloc(d->size * 2, sizeof *d->val);
68:     new_key  = (char**) calloc(d->size * 2, sizeof *d->key);
69:     new_hash = (unsigned*) calloc(d->size * 2, sizeof *d->hash);
70:     if (!new_val || !new_key || !new_hash) {
