102:   @param    key     Character string to use for key.
103:   @return   1 unsigned int on at least 32 bits.
104: 
105:   This hash function has been taken from an Article in Dr Dobbs Journal.
106:   This is normally a collision-free function, distributing keys evenly.
107:   The key is stored anyway in the struct so that collision can be avoided
108:   by comparing the key itself in last resort.
109:  */
110: /*--------------------------------------------------------------------------*/
111: unsigned dictionary_hash(const char * key)
112: {
113:     size_t      len ;
114:     unsigned    hash ;
115:     size_t      i ;
116: 
117:     if (!key)
118:         return 0 ;
119: 
120:     len = strlen(key);
121:     for (hash=0, i=0 ; i<len ; i++) {
122:         hash += (unsigned)key[i] ;
123:         hash += (hash<<10);
124:         hash ^= (hash>>6) ;
125:     }
126:     hash += (hash <<3);
127:     hash ^= (hash >>11);
