232: /*-------------------------------------------------------------------------*/
233: /**
234:   @brief    Set a value in a dictionary.
235:   @param    d       dictionary object to modify.
236:   @param    key     Key to modify or add.
237:   @param    val     Value to add.
238:   @return   int     0 if Ok, anything else otherwise
239: 
240:   If the given key is found in the dictionary, the associated value is
241:   replaced by the provided one. If the key cannot be found in the
242:   dictionary, it is added to it.
243: 
244:   It is Ok to provide a NULL value for val, but NULL values for the dictionary
245:   or the key are considered as errors: the function will return immediately
246:   in such a case.
247: 
248:   Notice that if you dictionary_set a variable to NULL, a call to
249:   dictionary_get will return a NULL value: the variable will be found, and
250:   its value (NULL) is returned. In other words, setting the variable
251:   content to NULL is equivalent to deleting the variable from the
252:   dictionary. It is not possible (in this implementation) to have a key in
253:   the dictionary without value.
254: 
255:   This function returns non-zero in case of failure.
256:  */
257: /*--------------------------------------------------------------------------*/
258: int dictionary_set(dictionary * d, const char * key, const char * val)
259: {
260:     size_t         i ;
261:     unsigned       hash ;
262: 
263:     if (d==NULL || key==NULL) return -1 ;
264: 
265:     /* Compute hash for this key */
266:     hash = dictionary_hash(key) ;
267:     /* Find if value is already in dictionary */
268:     if (d->n>0) {
269:         for (i=0 ; i<d->size ; i++) {
270:             if (d->key[i]==NULL)
271:                 continue ;
272:             if (hash==d->hash[i]) { /* Same hash value */
273:                 if (!strcmp(key, d->key[i])) {   /* Same key */
274:                     /* Found a value: modify and return */
275:                     if (d->val[i]!=NULL)
276:                         free(d->val[i]);
277:                     d->val[i] = (val ? xstrdup(val) : NULL);
278:                     /* Value has been modified: return */
279:                     return 0 ;
280:                 }
281:             }
282:         }
283:     }
284:     /* Add a new value */
285:     /* See if dictionary needs to grow */
286:     if (d->n==d->size) {
287:         /* Reached maximum size: reallocate dictionary */
288:         if (dictionary_grow(d) != 0)
289:             return -1;
290:     }
291: 
292:     /* Insert key in the first empty slot. Start at d->n and wrap at
293:        d->size. Because d->n < d->size this will necessarily
294:        terminate. */
295:     for (i=d->n ; d->key[i] ; ) {
296:         if(++i == d->size) i = 0;
297:     }
298:     /* Copy key */
299:     d->key[i]  = xstrdup(key);
300:     d->val[i]  = (val ? xstrdup(val) : NULL) ;
301:     d->hash[i] = hash;
302:     d->n ++ ;
303:     return 0 ;
304: }
