307: /**
308:   @brief    Delete a key in a dictionary
309:   @param    d       dictionary object to modify.
310:   @param    key     Key to remove.
311:   @return   void
312: 
313:   This function deletes a key in a dictionary. Nothing is done if the
314:   key cannot be found.
315:  */
316: /*--------------------------------------------------------------------------*/
317: void dictionary_unset(dictionary * d, const char * key)
318: {
319:     unsigned    hash ;
320:     size_t      i ;
321: 
322:     if (key == NULL || d == NULL) {
323:         return;
324:     }
325: 
326:     hash = dictionary_hash(key);
327:     for (i=0 ; i<d->size ; i++) {
328:         if (d->key[i]==NULL)
329:             continue ;
330:         /* Compare hash */
331:         if (hash==d->hash[i]) {
332:             /* Compare string, to avoid hash collisions */
333:             if (!strcmp(key, d->key[i])) {
334:                 /* Found key */
335:                 break ;
336:             }
337:         }
338:     }
339:     if (i>=d->size)
340:         /* Key not found */
341:         return ;
342: 
343:     free(d->key[i]);
344:     d->key[i] = NULL ;
345:     if (d->val[i]!=NULL) {
346:         free(d->val[i]);
347:         d->val[i] = NULL ;
348:     }
349:     d->hash[i] = 0 ;
350:     d->n -- ;
351:     return ;
352: }
