368:     size_t  i ;
369: 
370:     if (d==NULL || out==NULL) return ;
371:     if (d->n<1) {
372:         fprintf(out, "empty dictionary\n");
373:         return ;
374:     }
375:     for (i=0 ; i<d->size ; i++) {
376:         if (d->key[i]) {
377:             fprintf(out, "%20s\t[%s]\n",
378:                     d->key[i],
379:                     d->val[i] ? d->val[i] : "UNDEF");
380:         }
381:     }
382:     return ;
383: }

